function parcelCheckpoints(parcels, ranges) {
    return ranges.map(([start, end]) => {
        let sum = 0;
        for (let i = start; i < end; i++)
            sum += parcels[i];
        return sum;
    });
}

function parcelCheckpoints(parcels, ranges) {
    const prefix = [0];
    for (const count of parcels)
        prefix.push(prefix[prefix.length - 1] + count);
    return ranges.map(([start, end]) => prefix[end] - prefix[start]);
}
